<?php
$zipData = base64_decode('');
file_put_contents('deploy_staff.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy_staff.zip') === TRUE) {
    $zip->extractTo('../');
    $zip->close();
    unlink('deploy_staff.zip');
    // Clear compiled views manually
    $viewsPath = __DIR__ . '/../storage/framework/views';
    $files = glob($viewsPath . '/*.php');
    foreach ($files as $file) {
        if (is_file($file)) unlink($file);
    }
    echo '<h1>Staff Modal Colors & PIN Validation Fixed!</h1>';
    echo '<p>Colors are darker and PINs are now validated for uniqueness.</p>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>